import {recordFamilies} from './town-record-content.mjs';
import {recordView,validRecordCheck,validRecordRun,validRecordKeep,validRecordPart,startRecord,resumeRecord,pageRecord,dayRecord,toggleRecordSlot,presetRecord,collectRecord,resumeRecordRun,dayRecordRun,fullRecord,editRecordRun,checkRecordRun,sortRecord,answerRecord,checkRecordTask,toggleRecordColumn,rewriteRecord,planRecordMode,planRecordText,planRecordChoice,helpRecord,keepRecord,removeRecord} from './town-record-core.mjs';
import {stopSpeech} from './play-media.mjs';

const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const own=(o,k)=>Object.hasOwn(o,k);
const btn=(attrs,label,primary=false)=>`<button type="button" class="${primary?'primary':'secondary'}" ${attrs}>${esc(label)}</button>`;
const pages=['Make a useful record','Choose when to look','Design the sheet','Write the plan'];
const helpLabels=(s,ids)=>ids.map(id=>esc(s.help[id]?.title??'Earlier support')).join(', ');
const retained=label=>`<p class="record-retained" data-record-unreadable>${esc(label)} is kept exactly in your notebook download but cannot be read here.</p>`;
const value=v=>v===null?'Not read':`${v} cm`;
const dayLabel=(s,id)=>s.days.find(x=>x.id===id)?.label??id;
const timeLabel=(s,id)=>s.times.find(x=>x.id===id)?.label??id;
const cellLabel=(s,c)=>`${dayLabel(s,c.dayId)} ${timeLabel(s,c.timeId)}`;
const taskFrom=(s,id)=>s.questions.find(x=>x.id===id)||[s.sortTask,s.sheetTask,s.runTask].find(x=>x.id===id);
const selectedDay=(s,id)=>s.days.some(d=>d.id===id)?id:s.days[0]?.id;
function modelHeader(s){return `<aside class="record-model"><strong>${esc(s.fictionLabel)}</strong><p>${esc(s.datum)} Zero is a level at that fixed mark, not an empty river. The table supplies observations at particular times; it does not show every height between them.</p></aside>`;}
function newVisit(w){return `<section class="record-new"><h2>Try another invented week</h2><p>Change the week while keeping the question: what could a future reader know from this record?</p><label for="record-family">Week to investigate<select id="record-family" data-record-family>${recordFamilies.map(f=>`<option value="${esc(f.id)}"${w?.source.family===f.id?' selected':''}>${esc(f.title)}</option>`).join('')}</select></label>${btn('data-record-start','Open a new week',true)}</section>`;}
function visits(v){return !v.visits.length?'':`<details data-record-panel="visits"><summary>Your weeks (${v.visits.length})</summary><div class="record-actions">${v.visits.map(x=>x.readable?btn(`data-record-resume="${esc(x.id)}" aria-pressed="${v.current===x.id}"`,x.title||x.id):retained(`Week ${x.id}`)).join('')}</div></details>`;}
function storage(v){return `<details data-record-panel="storage"><summary>Download your notebook or make room</summary><p>Up to sixteen weeks and twelve collections per week are retained. Nothing is removed automatically. Download your notes before deliberately removing a selected week.</p><a class="secondary" href="#notes">Open notes and download</a>${v.visits.length?`<label for="record-remove-choice">Week to remove<select id="record-remove-choice" data-record-remove-choice><option value="">Choose a week</option>${v.visits.map(x=>`<option value="${esc(x.id)}">${esc(x.title||x.id)}${x.readable?'':' · retained unreadable'}</option>`).join('')}</select></label>${btn('data-record-remove','Remove only this week')}`:''}</details>`;}
function help(s,task,opened,scope='work'){
 const ids=[task?.hintId,task?.exampleId,task?.extraExampleId].filter(id=>typeof id==='string'&&s.help[id]);
 return `<div class="record-help"><div class="record-actions">${ids.map((id,i)=>btn(`data-record-help="${esc(id)}" data-record-help-for="${esc(task.id)}" data-record-scope="${scope}"`,i===0?'Open a hint':i===1?'Open a different example':'Open the small-grid example')).join('')}</div>${ids.filter(id=>opened.includes(id)).map(id=>`<aside data-record-help-text="${esc(id)}" data-record-help-for="${esc(task.id)}" tabindex="-1"><h4>${esc(s.help[id].title)}</h4><p>${esc(s.help[id].text)}</p></aside>`).join('')}</div>`;
}
function rawDescription(r){
 const s=r.source;
 if(r.kind==='choice'){const q=s.questions.find(q=>q.id===r.taskId);return q?.choices.find(c=>c.id===r.raw.choiceId)?.label??r.raw.choiceId;}
 if(r.kind==='sort')return s.cards.map(c=>`${c.text} — ${s.sortChoices.find(o=>o.id===r.raw.assignments?.[c.id])?.label??'not chosen'}`).join('\n');
 if(r.kind==='sheet')return r.raw.columns.map(id=>s.columns.find(c=>c.id===id)?.label??id).join('; ');
 return `Planned: ${r.raw.planned}; numeric readings: ${r.raw.recorded}; not read: ${r.raw.missing}; highest: ${r.raw.noNumeric?'No numeric reading':r.raw.highest}.`;
}
function checkedContext(r){const c=r.runContext;if(!c)return '';return `<aside class="record-check-context"><h5>Your collection when you checked</h5><p>${esc(c.source.title)}</p><ul>${c.readings.map(reading=>{const cell=c.source.cells.find(x=>x.id===reading.cellId);return `<li>${esc(cell?cellLabel(c.source,cell):'Earlier appointment')}: ${esc(value(reading.value))}</li>`;}).join('')}</ul><p>Full sheet opened: ${c.fullSheetSeen?'yes':'no'}. Requested collection support: ${c.help.length?helpLabels(c.source,c.help):'none requested'}.</p><p class="record-small">These are the supplied entries that were available when you checked.</p></aside>`;}

function checkCard(r,label,currentSource){return `<article class="record-history-item"><h4>${esc(label)}</h4>${JSON.stringify(r.source)!==JSON.stringify(currentSource)?'<p class="record-retained">This response has its own earlier source; it is not a new answer to the current week.</p>':''}<p>${esc(taskFrom(r.source,r.taskId)?.prompt??r.taskId)}</p><p class="record-raw">${esc(rawDescription(r))}</p><p data-record-feedback>${esc(r.feedback)}</p>${checkedContext(r)}<p class="record-small">Requested support before this response: ${r.helpBefore.length?helpLabels(r.source,r.helpBefore):'none requested'}. All shown teaching still supports this practice.</p></article>`;}
const unassignedCheck=c=>!c||typeof c!=='object'||!own(c,'taskId')||typeof c.taskId!=='string';
function taskHistory(w,task){const indices=w.checks.flatMap((c,i)=>c&&typeof c==='object'&&own(c,'taskId')&&c.taskId===task.id?[i]:[]),index=indices.at(-1),latest=index===undefined?undefined:w.checks[index],laterUnassigned=index!==undefined&&w.checks.slice(index+1).some(unassignedCheck),first=own(w.firstChecks||{},task.id)?w.firstChecks[task.id]:undefined;return `<section id="record-result-${esc(task.id)}" class="record-result" tabindex="-1">${latest===undefined?'':validRecordCheck(latest)?checkCard(latest,laterUnassigned?'Most recent readable check':'Latest checked version',w.source):retained('The latest checked version')}${own(w.firstChecks||{},task.id)?`<details data-record-panel="first-${esc(task.id)}"><summary>First checked version</summary>${validRecordCheck(first)?checkCard(first,'First checked version',w.source):retained('The first checked version')}</details>`:''}</section>`;}

function question(w,q){const raw=own(w.answers,q.id)?w.answers[q.id]:undefined,choice=raw&&typeof raw==='object'&&own(raw,'choiceId')?raw.choiceId:undefined;return `<details class="record-question" data-record-panel="question-${esc(q.id)}"><summary>${esc(q.prompt)}</summary>${q.context?`<aside class="record-example-context">${esc(q.context)}</aside>`:''}<div class="record-choices" role="group" aria-label="${esc(q.prompt)}">${q.choices.map(c=>btn(`data-record-answer="${esc(q.id)}" data-choice="${esc(c.id)}" aria-pressed="${choice===c.id}"`,c.label)).join('')}</div>${btn(`data-record-check="${esc(q.id)}"`,'Check this idea',true)}${help(w.source,q,w.help)}${taskHistory(w,q)}</details>`;}
function questions(w,page){return w.source.questions.filter(q=>q.page===page).map(q=>question(w,q)).join('');}
function method(w){const s=w.source,raw=own(w.answers,s.sortTask.id)?w.answers[s.sortTask.id]:undefined,assignments=raw&&typeof raw==='object'&&own(raw,'assignments')&&raw.assignments&&typeof raw.assignments==='object'?raw.assignments:{};return `<h2 id="record-heading" tabindex="-1">What makes a useful record?</h2><p>${esc(s.story)}</p>${s.teaching.map(t=>`<p>${esc(t)}</p>`).join('')}<section class="record-card-sort"><h3>${esc(s.sortTask.prompt)}</h3><p>Practice cards, separate from the week’s observations. The height cards refer to Willowbank’s marked post. Open a card and choose what its description still needs.</p>${s.cards.map((card,i)=>`<details data-record-panel="card-${esc(card.id)}"${i===0?' open':''}><summary>Card ${i+1}: ${esc(card.text)}</summary><div class="record-choices" role="group" aria-label="Classify card ${i+1}">${s.sortChoices.map(c=>btn(`data-record-card="${esc(card.id)}" data-choice="${esc(c.id)}" aria-pressed="${own(assignments,card.id)&&assignments[card.id]===c.id}"`,c.label)).join('')}</div></details>`).join('')}${btn(`data-record-check="${esc(s.sortTask.id)}"`,'Check these card choices',true)}${help(s,s.sortTask,w.help)}${taskHistory(w,s.sortTask)}</section><label for="record-rewrite">Rewrite one record in your own words (optional)<textarea id="record-rewrite" data-record-rewrite data-record-draft maxlength="1200" rows="3">\n${esc(w.rewrite)}</textarea></label><p class="record-small">Your writing is kept as writing. It is not checked for keywords.</p>${questions(w,0)}`;}
function dayChooser(s,id,attr,label){return `<label class="record-day-choice">${esc(label)}<select ${attr}>${s.days.map(d=>`<option value="${esc(d.id)}"${selectedDay(s,id)===d.id?' selected':''}>${esc(d.label)}</option>`).join('')}</select></label>`;}
function slotButton(s,c,selected){return btn(`data-record-slot="${esc(c.id)}" aria-label="${esc(cellLabel(s,c))} · ${selected.has(c.id)?'selected':'not selected'}" aria-pressed="${selected.has(c.id)}"`,`${timeLabel(s,c.timeId)} · ${selected.has(c.id)?'selected':'not selected'}`);}
function planning(w){const s=w.source,selected=new Set(w.planning);return `<section class="record-planning"><h3>Plan your observation appointments</h3><p class="record-shape">This sheet has ${s.days.length} days × ${s.times.length} time slots per day. A slot is an appointment, not necessarily a numeric reading.</p><p>Selected appointments: <strong data-record-planned>${w.planning.length}</strong>. Observer visits available in this invented exercise: <strong>${s.budget}</strong>. ${w.planning.length>s.budget?'This plan needs more observer visits than the town has set aside. You can still test it and compare.':'You can test a larger plan too; the budget is a comparison, not a lock.'}</p><div class="record-actions">${s.presets.map(p=>btn(`data-record-preset="${esc(p.id)}"`,p.label)).join('')}</div><p>Or select individual slots. Values stay hidden until you collect that selection.</p><div class="record-week-planner record-table-region" role="region" aria-label="Whole-week appointment selection" tabindex="0"><table><caption>Planned slots · no readings collected here</caption><thead><tr><th scope="col">Day</th>${s.times.map(t=>`<th scope="col">${esc(t.label)}</th>`).join('')}</tr></thead><tbody>${s.days.map(d=>`<tr><th scope="row">${esc(d.label)}</th>${s.times.map(t=>{const c=s.cells.find(c=>c.dayId===d.id&&c.timeId===t.id);return `<td>${c?slotButton(s,c,selected):'No stored slot'}</td>`;}).join('')}</tr>`).join('')}</tbody></table></div><div class="record-day-planner">${dayChooser(s,w.dayId,'data-record-day','Planning day')}<div class="record-day-slots">${s.cells.filter(c=>c.dayId===selectedDay(s,w.dayId)).map(c=>slotButton(s,c,selected)).join('')||'<p>No stored slots for this day.</p>'}</div></div><div class="record-actions">${btn('data-record-collect','Collect these readings',true)}</div><p class="record-small">Collecting shows only the supplied observations at your selected appointments. It does not create a real observation.</p></section>`;}
function chart(run){const s=run.source,selected=new Set(run.selection),saved=new Map(run.readings.map(r=>[r.cellId,r.value])),shown=s.cells.filter(c=>selected.has(c.id)||run.fullSheet),dayIndices=new Map(s.days.map((d,i)=>[d.id,i])),minutes=new Map(s.times.map(t=>[t.id,t.minute])),start=s.times[0].minute,end=(s.days.length-1)*1440+s.times.at(-1).minute;const left=56,right=682,top=20,bottom=226,x=c=>left+((dayIndices.get(c.dayId)*1440+minutes.get(c.timeId))-start)*(right-left)/Math.max(1,end-start),y=v=>bottom-v*(bottom-top)/200;return `<div class="record-chart-region" role="region" aria-label="Point plot of supplied observations; scroll if needed" tabindex="0"><svg class="record-chart" viewBox="0 0 720 306" role="img" aria-label="Height in centimetres above the fixed mark at supplied day and time. Points only; no heights are invented between observations."><text x="56" y="12">Height (cm from the fixed mark)</text>${[0,50,100,150,200].map(n=>`<line x1="${left}" x2="${right}" y1="${y(n)}" y2="${y(n)}" class="record-grid-line"/><text x="45" y="${y(n)+4}" text-anchor="end">${n}</text>`).join('')}<line x1="${left}" x2="${right}" y1="${bottom}" y2="${bottom}" class="record-axis"/>${s.days.map(d=>`<text x="${x({dayId:d.id,timeId:s.times[0].id})}" y="277" text-anchor="middle">${esc(d.label.slice(0,3))}</text>`).join('')}<text x="370" y="299" text-anchor="middle">Source day and appointment time · exact values in the table</text>${shown.map(c=>{const v=selected.has(c.id)?saved.get(c.id):c.value,cls=selected.has(c.id)?'record-sampled':'record-other',label=`${cellLabel(s,c)}: ${value(v)}${selected.has(c.id)?' · collected':' · other supplied reading'}`;return v===null?`<path d="M ${x(c)} 240 l 5 5 l -5 5 l -5 -5 z" class="record-missing ${cls}" data-record-point="${esc(c.id)}" data-state="missing" aria-label="${esc(label)}"><title>${esc(label)}</title></path>`:`<circle cx="${x(c)}" cy="${y(v)}" r="5" class="${cls}" data-record-point="${esc(c.id)}" data-state="${selected.has(c.id)?'sampled':'supplied'}" aria-label="${esc(label)}"><title>${esc(label)}</title></circle>`;}).join('')}</svg></div><p class="record-legend"><span><i class="record-legend-dot"></i>Collected numeric reading</span>${run.fullSheet?'<span><i class="record-legend-dot other"></i>Other supplied numeric reading</span>':''}<span><i class="record-legend-missing"></i>Collected Not read · no number</span>${run.fullSheet?'<span><i class="record-legend-missing other"></i>Other supplied Not read</span>':''}</p>`;}
function readingTable(run){const s=run.source,selected=new Set(run.selection),saved=new Map(run.readings.map(r=>[r.cellId,r.value]));const shown=s.cells.filter(c=>selected.has(c.id)||run.fullSheet);return `<div class="record-table-region" role="region" aria-label="Exact collected and comparison readings" tabindex="0"><table data-record-readings><caption>${run.fullSheet?'Collected and other supplied observations':'Only your collected appointments'}</caption><thead><tr><th scope="col">Day</th><th scope="col">Actual time</th><th scope="col">Reading</th><th scope="col">Source</th></tr></thead><tbody>${shown.map(c=>`<tr data-record-reading="${esc(c.id)}"><th scope="row">${esc(dayLabel(s,c.dayId))}</th><td>${esc(timeLabel(s,c.timeId))}</td><td>${esc(value(selected.has(c.id)?saved.get(c.id):c.value))}</td><td>${selected.has(c.id)?'Collected':'Other supplied'}</td></tr>`).join('')}</tbody></table></div>`;}
function dayReadings(run){const s=run.source,selected=new Set(run.selection),saved=new Map(run.readings.map(r=>[r.cellId,r.value]));const rows=s.cells.filter(c=>c.dayId===selectedDay(s,run.dayId)&&(run.fullSheet||selected.has(c.id)));return `<section class="record-result-day">${dayChooser(s,run.dayId,'data-record-run-day','Result day')}<ul>${rows.map(c=>`<li>${esc(timeLabel(s,c.timeId))}: ${esc(value(selected.has(c.id)?saved.get(c.id):c.value))} · ${selected.has(c.id)?'collected':'other supplied'}</li>`).join('')||'<li>No collected observation for this day.</li>'}</ul></section>`;}
function runHistory(run){const latest=run.checks.at(-1);return `<section id="record-run-check" tabindex="-1" class="record-result">${latest===undefined?'':validRecordCheck(latest)?checkCard(latest,'Latest checked description',run.source):retained('The latest numeric check')}${own(run,'firstCheck')?`<details data-record-panel="run-first-${esc(run.id)}"><summary>First checked description</summary>${validRecordCheck(run.firstCheck)?checkCard(run.firstCheck,'First checked description',run.source):retained('The first numeric check')}</details>`:''}</section>`;}
function repeatCollection(w,run){const index=w.runs.indexOf(run);if(index<0)return null;const earlier=w.runs.slice(0,index).findIndex(r=>validRecordRun(r)&&JSON.stringify(r.source)===JSON.stringify(run.source)&&r.selection.length===run.selection.length&&r.selection.every(id=>run.selection.includes(id)));return earlier<0?null:earlier+1;}
function runUI(w,run){if(!run)return w.currentRun?retained('The selected collection'):'<p class="record-invitation">Choose a schedule and collect its readings to see what it catches.</p>';const s=run.source,d=run.drafts,repeated=repeatCollection(w,run);return `<section class="record-run" id="record-run-result" tabindex="-1"><h3>${esc(s.title)} · collected schedule</h3>${repeated===null?'':`<p class="record-repeat">Repeated collection of supplied data: this is the same frozen week and appointments as Collection ${repeated}. It is not a new real observation.</p>`}<p class="record-shape">This collection’s own sheet has ${s.days.length} days × ${s.times.length} time slots per day.</p>${JSON.stringify(s)!==JSON.stringify(w.source)?'<p class="record-retained">This collection uses its own earlier week. Changing the planning grid does not change it.</p>':''}<p>Your planning selection above is a separate draft. The table below belongs to this saved collection, even if you change the next plan.</p>${chart(run)}${dayReadings(run)}${readingTable(run)}<div class="record-actions">${btn(`data-record-full="${!run.fullSheet}"`,run.fullSheet?'Hide full sheet':'Compare with the full sheet')}</div><p>${run.fullSheet?'The other supplied readings are visible as support. Their highest value is only the highest supplied reading, not proof of the continuous peak.':'You have collected only the selected appointments. Uncollected heights are not shown.'}</p>${run.fullSheetSeen?'<p class="record-small">The full sheet has been opened for this collection. Hiding it does not erase that support.</p>':''}${run.fullSheet?'<p class="record-comparison">For sets with numeric readings, a selection contained in a larger set cannot have a higher maximum than that larger set. Two different schedules may not contain one another: more appointments alone does not tell you which catches the higher reading. Neither shows every moment between appointments.</p>':''}<section class="record-run-questions"><h4>${esc(s.runTask.prompt)}</h4><p>Use the readings above. A slot saying Not read is still a planned appointment, but it is not a numeric reading.</p><div class="record-numbers">${[['planned','Planned appointments'],['recorded','Numeric readings'],['missing','Not-read appointments'],['highest','Highest numeric reading (cm)']].map(([id,label])=>`<label for="record-run-${id}">${esc(label)}<input id="record-run-${id}" type="text" inputmode="text" autocomplete="off" spellcheck="false" maxlength="40" data-record-run-field="${id}" data-record-draft value="${esc(d[id])}"></label>`).join('')}</div><label class="record-checkbox"><input type="checkbox" data-record-run-field="noNumeric"${d.noNumeric?' checked':''}>No numeric reading was collected; there is no numeric maximum.</label><p class="record-small">Use numbers or fractions, not expressions. If you select No numeric reading, the highest-number draft stays kept but is not your claim.</p>${btn('data-record-check-run','Check my description',true)}${help(s,s.runTask,run.help,'run')}${runHistory(run)}</section></section>`;}
function sampling(w,v){return `<h2 id="record-heading" tabindex="-1">When would you look?</h2><p>A record can only show the moments that were observed. Try different schedules over the same supplied week; no schedule here is labelled best.</p>${planning(w)}<details data-record-panel="collections"><summary>Your collected schedules (${w.runs.length})</summary><div class="record-actions">${(v.runs||[]).map((r,i)=>{const repeated=r.readable?repeatCollection(w,w.runs[i]):null;return r.readable?btn(`data-record-run="${esc(r.id)}" aria-pressed="${w.currentRun===r.id}"`,`${r.title||r.id}${repeated===null?'':` · repeat of Collection ${repeated}`}`):retained(`Collection ${r.id}`);}).join('')||'<p>No collection yet.</p>'}</div></details>${runUI(w,v.run)}${questions(w,1)}`;}
function sheet(w){const s=w.source;return `<h2 id="record-heading" tabindex="-1">Make the sheet readable</h2><p>Choose headings a future reader can use. You may keep context too; a picture or a name does not replace a measurement.</p><div class="record-columns" role="group" aria-label="Record-sheet columns">${s.columns.map(c=>btn(`data-record-column="${esc(c.id)}" aria-pressed="${w.columns.includes(c.id)}"`,c.label)).join('')}</div><section class="record-designed-sheet"><h3>Your selected headings</h3><ol>${w.columns.map(id=>`<li>${esc(s.columns.find(c=>c.id===id)?.label??id)}</li>`).join('')||'<li>No headings chosen yet.</li>'}</ol></section>${btn(`data-record-check="${esc(s.sheetTask.id)}"`,'Check the headings',true)}${help(s,s.sheetTask,w.help)}${taskHistory(w,s.sheetTask)}<aside class="record-example-context"><h3>A different example: three kinds of entry</h3><table><thead><tr><th>Entry</th><th>What it says</th></tr></thead><tbody><tr><td>0 cm</td><td>A numeric level at the fixed mark.</td></tr><tr><td>Not read — observer absent</td><td>No numeric observation.</td></tr><tr><td>Unexplained blank</td><td>A future reader cannot tell why it is blank.</td></tr></tbody></table></aside>${questions(w,2)}`;}
function keptCard(k,label){return `<article class="record-kept"><h3>${esc(label)}</h3><p>${esc(k.source.title)}</p>${k.renderedParts.map(p=>`<section><h4>${esc(p.title)}</h4>${own(k.plan,p.id)&&!validRecordPart(k.plan[p.id])?retained('The earlier writing for this kept part'):`<p class="record-raw">${p.text?esc(p.text):'Not yet written.'}</p>`}<p class="record-small">${p.mode==='supplied'?(k.supportedParts.some(part=>part.partId===p.id)?'Supplied sentence selected as support.':'No supplied sentence selected; this part is unfinished.'):'Own writing, ungraded.'}</p></section>`).join('')}<p class="record-small">This is a kept contribution, not a grade or a completion gate.</p></article>`;}
function keptHistory(w){return `<details data-record-panel="kept"><summary>Instructions kept · first and latest</summary>${['firstKept','kept'].map((key,i)=>own(w,key)?validRecordKeep(w[key])?keptCard(w[key],i===0?'First kept instructions':'Latest kept instructions'):retained(i===0?'First kept instructions':'Latest kept instructions'):'').join('')||'<p>No kept instructions yet. An unfinished plan can be worth keeping.</p>'}</details>`;}
function plan(w){const s=w.source;return `<h2 id="record-heading" tabindex="-1">Leave instructions for a future reader</h2><p>Write your own words or choose a supplied sentence. You can keep an unfinished plan, and change it later. No earlier check is required.</p><details data-record-panel="plan-context"><summary>Your earlier materials</summary><p>Selected sheet headings: ${w.columns.map(id=>esc(s.columns.find(c=>c.id===id)?.label??id)).join('; ')||'not chosen yet'}.</p><p>Your method rewrite: ${w.rewrite?esc(w.rewrite):'not written yet'}.</p><ul>${w.runs.filter(validRecordRun).map(r=>`<li>${esc(r.id)}: ${r.plannedCount} planned appointments; original readings remain in the collected schedules.</li>`).join('')||'<li>No collected schedule yet.</li>'}</ul></details>${s.parts.map(part=>{const stored=own(w.plan,part.id),p=stored?w.plan[part.id]:{mode:'own',own:'',choiceId:''};if(stored&&!validRecordPart(p))return `<section class="record-plan-part"><h3>${esc(part.title)}</h3>${retained('The earlier writing for this part')}</section>`;return `<section class="record-plan-part"><h3>${esc(part.title)}</h3><div class="record-actions">${['own','supplied'].map(mode=>btn(`data-record-plan-mode="${esc(part.id)}" data-mode="${mode}" aria-pressed="${p.mode===mode}"`,mode==='own'?'Use my own words':'Choose and adapt')).join('')}</div>${p.mode==='own'?`<label for="record-part-${esc(part.id)}">Your words (optional)<textarea id="record-part-${esc(part.id)}" data-record-plan-text="${esc(part.id)}" data-record-draft maxlength="1200" rows="3">\n${esc(p.own)}</textarea></label>`:`<label for="record-choice-${esc(part.id)}">A supplied sentence<select id="record-choice-${esc(part.id)}" data-record-plan-choice="${esc(part.id)}"><option value="" disabled${!part.options.some(c=>c.id===p.choiceId)?' selected':''}>Choose a sentence</option>${part.options.map(c=>`<option value="${esc(c.id)}"${p.choiceId===c.id?' selected':''}>${esc(c.text)}</option>`).join('')}</select></label><p class="record-supplied">${esc(part.options.find(c=>c.id===p.choiceId)?.text??'No supplied sentence selected yet.')}</p><p class="record-small">This supplied sentence is support. Your own-writing draft stays kept when you switch back.</p>`}</section>`;}).join('')}<section class="record-plan-result" id="record-plan-result" tabindex="-1">${btn('data-record-keep','Keep these instructions',true)}${own(w,'kept')?`<p class="record-closing">${esc(validRecordKeep(w.kept)?w.kept.source.closing:s.closing)}</p>`:''}${keptHistory(w)}</section>${s.questions.filter(q=>q.page===3).map(q=>question(w,q)).join('')}`;}
export const recordEntry=()=>'<section class="record-entry"><h2>What should the town write down?</h2><p>Try observation schedules, keep gaps honest, and design a record a future reader could understand.</p><a class="secondary" href="#learn/science/records">Open the Town Record</a></section>';
export const recordRefusal=()=>'<section class="record-page"><h1>The Town Record</h1><h2>Earlier work is safe</h2><p>This page could not keep the newly shown support safely. No new observations or answers have been revealed. You can open notes to download your notebook or choose another destination.</p><a class="secondary" href="#desk">Keeper’s Desk</a><a class="secondary" href="#notebook">Field notebooks</a><a class="secondary" href="#notes">Open notes</a><a class="secondary" href="#pathways/science">Other science investigations</a><p id="record-status" role="status" tabindex="-1"></p></section>';
export function recordPage(state){const v=recordView(state),w=v.work;const head='<div class="record-page" data-record-root><header class="record-header"><a class="secondary" href="#desk">Back to the Keeper’s Desk</a><h1>The Town Record</h1><p>Choose what to write. Try when to look. Leave a book someone else can understand.</p></header>';if(v.status==='unavailable')return head+'<h2 id="record-heading" tabindex="-1">Earlier record format retained</h2><p>This version cannot edit that format. Your exact notebook stays downloadable, and all other destinations remain open.</p><a class="secondary" href="#notes">Open notes</a><p id="record-status" role="status" tabindex="-1"></p></div>';
 const status='<p id="record-status" role="status" aria-live="polite" tabindex="-1"></p><div data-record-pending-actions hidden><p>Some visible words have not been saved. Edit the marked field or deliberately restore the saved words.</p>'+btn('data-record-restore','Restore saved words')+'</div>';
 if(!w)return head+`<h2 id="record-heading" tabindex="-1">The librarian’s empty book</h2><p>What would a future reader need to know? Explore an invented week, compare the moments you might observe, and make your own record plan.</p>${v.status==='unreadable'?retained('The selected week'):''}${newVisit(null)}${visits(v)}${v.visits.length?storage(v):''}${status}<footer><a class="secondary" href="#pathways/science">Other science investigations</a><a class="secondary" href="#notebook">Field notebooks</a><a class="secondary" href="#notes">Grown-up notes</a></footer></div>`;
 return head+`<p class="record-visit-title">${esc(w.source.title)}</p>${modelHeader(w.source)}${w.checks.some(unassignedCheck)?'<p class="record-retained" data-record-unassigned-check>A saved check cannot be matched to a question here. It stays unchanged in your notebook download.</p>':''}<nav class="record-pages" aria-label="Town Record pages">${pages.map((name,i)=>btn(`data-record-page="${i}" aria-current="${w.page===i?'step':'false'}"`,name)).join('')}</nav><section class="record-turn">${[method,()=>sampling(w,v),sheet,plan][w.page](w)}</section><nav class="record-page-arrows" aria-label="Previous and next page">${w.page>0?btn(`data-record-page="${w.page-1}"`,`Previous: ${pages[w.page-1]}`):''}${w.page<3?btn(`data-record-page="${w.page+1}"`,`Next: ${pages[w.page+1]}`,true):''}</nav>${status}${newVisit(w)}${visits(v)}${storage(v)}<details data-record-panel="grownups"><summary>Grown-ups · what this record can show</summary><p>All observations here are invented. A selected schedule is a subset of a supplied table, not a real observation or a flood-monitoring recommendation. No heights are invented between appointments. A full-sheet maximum cannot establish the real continuous peak.</p><p>Requested support, source familiarity, original checked responses and supplied versus original writing stay separate. These activities do not establish independent proficiency or mastery.</p></details><footer><a class="secondary" href="#pathways/science">Other science investigations</a><a class="secondary" href="#notebook">Field notebooks</a><a class="secondary" href="#notes">Grown-up notes</a></footer></div>`;
}
export function recordNotes(state){if(!own(state,'townRecord'))return '';const v=recordView(state);return `<details class="panel record-notes"><summary>Town Record · fictional observations and protocols</summary><p>Source-owned weeks, selected schedules, raw writing, original first/latest checks and kept instructions stay separate. All are supported investigations; no real observations, proficiency or story completion are inferred.</p>${v.status==='unavailable'?'<p>Earlier format retained unchanged.</p>':v.visits.map(x=>x.readable?`<p>${esc(x.title||x.id)}: ${v.root.visits[x.id].runs.length} collections and ${v.root.visits[x.id].checks.length} checked task records retained. ${own(v.root.visits[x.id],'kept')?'Instructions have a kept version.':'No kept instructions yet.'}</p>`:retained(`Week ${x.id}`)).join('')}<p>Malformed or future entries remain exact in the raw download; healthy siblings remain open. Original outcomes are not regraded.</p><details><summary>Exact frozen sources and writing</summary><pre>${esc(JSON.stringify(state.townRecord,null,2))}</pre></details></details>`;}

let removeGuards=()=>{},pendingNavigation=()=>false;
export const guardRecordNavigation=()=>pendingNavigation();
export function bindRecord(state,{save,render,focus,canExport,exposeFacts,explorerId,isActive}={}){
 removeGuards();removeGuards=()=>{};const root=document.querySelector('[data-record-root]');if(!root)return;
 const owner=explorerId?.(),route=location.hash,o={canExport,exposeFacts},dirty=new Set();
 const live=el=>root.isConnected&&el?.isConnected&&root.contains(el)&&location.hash===route&&explorerId?.()===owner&&(!isActive||isActive());
 const say=(text,take=false)=>{const el=root.querySelector('#record-status');if(el){el.textContent=text;if(take)el.focus();}};
 const pendingMessage='Your visible words have not been saved. Edit the marked field to try again, or copy them and choose Restore saved words before continuing.';
 const pendingUI=()=>{const el=root.querySelector('[data-record-pending-actions]');if(el)el.hidden=!dirty.size;};
 const redraw=(message='',target='#record-heading')=>{const panels=new Map([...root.querySelectorAll('details[data-record-panel]')].map(n=>[n.dataset.recordPanel,n.open]));stopSpeech();save?.();render?.();const next=document.querySelector('[data-record-root]');next?.querySelectorAll('details[data-record-panel]').forEach(n=>{if(panels.has(n.dataset.recordPanel))n.open=panels.get(n.dataset.recordPanel);});const status=next?.querySelector('#record-status');if(status)status.textContent=message;const el=next?.querySelector(target);if(el)el.focus();if(!el||document.activeElement!==el)focus?.('#record-heading');};
 const fail=()=>say('This change could not be kept safely. Earlier work stays unchanged. Download your notebook before making room, or choose another week.',true);
 const act=(el,fn,message='',target='#record-heading')=>{if(!live(el))return;if(dirty.size){say(pendingMessage,true);return;}const result=fn();if(!result)return fail();if(result.recorded===false){say(result.feedback,true);return;}redraw(message,target);};
 const on=(selector,fn)=>root.querySelectorAll(selector).forEach(el=>el.addEventListener('click',()=>{if(live(el))fn(el);}));
 const capCheck=fn=>recordView(state).work?.checks.length>=24?{recorded:false,feedback:'This week retains twenty-four checks. Your earlier responses stay unchanged. You can edit and keep instructions, revisit any page, or open another week for more checks.'}:fn();
 on('[data-record-start]',el=>act(el,()=>recordView(state).visits.length>=16?{recorded:false,feedback:'Sixteen weeks are retained. Download your notebook, then deliberately remove a selected week to make room. Earlier work stays available.'}:startRecord(state,root.querySelector('[data-record-family]')?.value,o),'A new invented week is open. Earlier work stays retained.'));
 on('[data-record-resume]',el=>act(el,()=>resumeRecord(state,el.dataset.recordResume,o),'Original week resumed.'));
 on('[data-record-page]',el=>act(el,()=>pageRecord(state,Number(el.dataset.recordPage),o)));
 on('[data-record-preset]',el=>act(el,()=>presetRecord(state,el.dataset.recordPreset,o),'Planning selection changed; saved collections stay unchanged.',`[data-record-preset="${el.dataset.recordPreset}"]`));
 on('[data-record-slot]',el=>act(el,()=>toggleRecordSlot(state,el.dataset.recordSlot,o),'Appointment selection kept.',`[data-record-slot="${el.dataset.recordSlot}"]`));
 on('[data-record-collect]',el=>act(el,()=>{const w=recordView(state).work;if(w?.runs.length>=12)return {recorded:false,feedback:'This week retains twelve collections. You can resume any earlier collection, edit your plan or open another week to collect more.'};if(!w?.planning.length)return {recorded:false,feedback:'Select at least one appointment before collecting.'};return collectRecord(state,o);},'The selected supplied readings are kept. Your planning draft is separate.','#record-run-result'));
 on('[data-record-run]',el=>act(el,()=>resumeRecordRun(state,el.dataset.recordRun,o),'Earlier collection and drafts resumed.','#record-run-result'));
 on('[data-record-full]',el=>act(el,()=>fullRecord(state,el.dataset.recordFull==='true',o),el.dataset.recordFull==='true'?'Full supplied sheet opened as support.':'Full sheet folded; prior support stays recorded.','#record-run-result'));
 on('[data-record-card]',el=>act(el,()=>sortRecord(state,el.dataset.recordCard,el.dataset.choice,o),'Card choice kept.',`[data-record-card="${el.dataset.recordCard}"][data-choice="${el.dataset.choice}"]`));
 on('[data-record-answer]',el=>act(el,()=>answerRecord(state,el.dataset.recordAnswer,el.dataset.choice,o),'Idea kept. You can still change it.',`[data-record-answer="${el.dataset.recordAnswer}"][data-choice="${el.dataset.choice}"]`));
 on('[data-record-check]',el=>act(el,()=>capCheck(()=>checkRecordTask(state,el.dataset.recordCheck,o)),'Checked version kept as answered.',`#record-result-${el.dataset.recordCheck}`));
 on('[data-record-check-run]',el=>act(el,()=>capCheck(()=>recordView(state).run?.checks.length>=12?{recorded:false,feedback:'This collection retains twelve numeric checks. Earlier versions stay unchanged. You can edit its answers, try another collection or keep your instructions.'}:checkRecordRun(state,o)),'Checked description kept as answered.','#record-run-check'));
 on('[data-record-help]',el=>act(el,()=>helpRecord(state,el.dataset.recordHelp,el.dataset.recordScope,o),'Support kept before showing it.',`[data-record-help-for="${el.dataset.recordHelpFor}"][data-record-help-text="${el.dataset.recordHelp}"]`));
 on('[data-record-column]',el=>act(el,()=>toggleRecordColumn(state,el.dataset.recordColumn,o),'Sheet heading choice kept.',`[data-record-column="${el.dataset.recordColumn}"]`));
 on('[data-record-plan-mode]',el=>act(el,()=>planRecordMode(state,el.dataset.recordPlanMode,el.dataset.mode,o),'Both the own-writing draft and supplied choice remain kept.',`[data-record-plan-mode="${el.dataset.recordPlanMode}"][data-mode="${el.dataset.mode}"]`));
 on('[data-record-keep]',el=>act(el,()=>keepRecord(state,o),'Instructions kept. First and latest versions stay separate.','#record-plan-result'));
 on('[data-record-remove]',el=>{if(dirty.size)return say(pendingMessage,true);const id=root.querySelector('[data-record-remove-choice]')?.value;if(!id)return say('Choose the week to remove.',true);if(!window.confirm('Remove only this selected week and its original sources, collections, writing and kept instructions? Download your notebook first if you want to retain a copy.'))return;if(!live(el))return;act(el,()=>removeRecord(state,id,true,o),'Selected week removed. Other work remains available.');});
 const selectChange=(selector,fn,target,stored)=>root.querySelectorAll(selector).forEach(el=>el.addEventListener('change',()=>{if(!live(el))return;const before=stored(el);if(dirty.size){el.value=before;say(pendingMessage,true);return;}act(el,()=>{const r=fn(el);if(!r||r.recorded===false)el.value=before;return r;},'Selection kept.',typeof target==='function'?target(el):target);}));
 selectChange('[data-record-day]',el=>dayRecord(state,el.value,o),'[data-record-day]',()=>{const w=recordView(state).work;return selectedDay(w.source,w.dayId);});
 selectChange('[data-record-run-day]',el=>dayRecordRun(state,el.value,o),'[data-record-run-day]',()=>{const r=recordView(state).run;return selectedDay(r.source,r.dayId);});
 selectChange('[data-record-plan-choice]',el=>planRecordChoice(state,el.dataset.recordPlanChoice,el.value,o),el=>`[data-record-plan-choice="${el.dataset.recordPlanChoice}"]`,el=>{const plan=recordView(state).work.plan,key=el.dataset.recordPlanChoice;return own(plan,key)&&validRecordPart(plan[key])?plan[key].choiceId:'';});
 root.querySelectorAll('[data-record-run-field="noNumeric"]').forEach(el=>el.addEventListener('change',()=>{if(!live(el))return;const before=recordView(state).run.drafts.noNumeric;if(dirty.size){el.checked=before;return say(pendingMessage,true);}act(el,()=>{const r=editRecordRun(state,'noNumeric',el.checked,o);if(!r)el.checked=before;return r;},'Maximum claim kept. Your numeric draft stays available.','[data-record-run-field="noNumeric"]');}));
 const input=(el,key,fn)=>el.addEventListener('input',()=>{if(!live(el))return;if(!fn(el.value)){dirty.add(key);el.setAttribute('aria-invalid','true');pendingUI();say(pendingMessage);return;}dirty.delete(key);el.removeAttribute('aria-invalid');save?.();pendingUI();say(dirty.size?pendingMessage:'Words saved.');});
 root.querySelectorAll('[data-record-run-field]:not([type="checkbox"])').forEach(el=>input(el,`run-${el.dataset.recordRunField}`,raw=>editRecordRun(state,el.dataset.recordRunField,raw,o)));
 root.querySelectorAll('[data-record-rewrite]').forEach(el=>input(el,'rewrite',raw=>rewriteRecord(state,raw,o)));
 root.querySelectorAll('[data-record-plan-text]').forEach(el=>input(el,`part-${el.dataset.recordPlanText}`,raw=>planRecordText(state,el.dataset.recordPlanText,raw,o)));
 on('[data-record-restore]',el=>{if(!live(el)||!window.confirm('Discard the visible unsaved edits and restore this page’s last saved words? Earlier saved work stays unchanged.'))return;dirty.clear();redraw('Last saved words restored.');});
 const guard=e=>{if(e.type==='keydown'&&!['Enter',' '].includes(e.key))return;if(!root.isConnected||location.hash!==route||explorerId?.()!==owner||!dirty.size)return;const target=e.target;if(target?.closest?.('[data-record-draft],[data-record-restore]'))return;if(target?.closest?.('button,a,input,select,summary')){e.preventDefault();e.stopImmediatePropagation();say(pendingMessage);}};
 pendingNavigation=()=>{if(!root.isConnected||explorerId?.()!==owner||!dirty.size)return false;history.replaceState(null,'',route);say(pendingMessage);return true;};
 const beforeLeave=e=>{if(dirty.size&&root.isConnected){e.preventDefault();e.returnValue='';}};
 document.addEventListener('click',guard,true);document.addEventListener('keydown',guard,true);window.addEventListener('beforeunload',beforeLeave);
 removeGuards=()=>{document.removeEventListener('click',guard,true);document.removeEventListener('keydown',guard,true);window.removeEventListener('beforeunload',beforeLeave);pendingNavigation=()=>false;};
}
